<script>(function(){const cards=Array.from(document.querySelectorAll('.commercial-item'));function filter(card){const s=card.querySelector('.line-supplier'),m=card.querySelector('.line-method'),d=card.querySelector('.line-destination');if(!d)return;Array.from(d.options).forEach(o=>{if(!o.value)return;o.hidden=o.dataset.supplier!==s.value||(m.value&&o.dataset.method!==m.value);if(o.hidden&&o.selected)d.value='';});}function totals(){const groups={};cards.forEach(c=>{const r=c.querySelector('.line-rate'),t=c.querySelector('.line-total'),s=c.querySelector('.line-supplier'),amount=(parseFloat(r.value)||0)*(parseFloat(r.dataset.quantity)||1);t.value=amount.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});const label=s.options[s.selectedIndex]?.text.split(' · ')[0]||'Unassigned';groups[label]=(groups[label]||0)+amount;});const target=document.getElementById('supplierGroupTotals');if(target)target.innerHTML=Object.entries(groups).map(([n,t])=>'<div class="tile"><div class="label">'+n+'</div><div>TSh '+t.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+'</div></div>').join('');}cards.forEach(c=>{['.line-supplier','.line-method'].forEach(s=>c.querySelector(s)?.addEventListener('change',()=>filter(c)));c.querySelector('.line-rate')?.addEventListener('input',totals);filter(c);});document.getElementById('applySupplierGroup')?.addEventListener('click',()=>{const s=document.getElementById('bulk_supplier').value,m=document.getElementById('bulk_method').value;cards.filter(c=>c.querySelector('.group-select').checked).forEach(c=>{if(s)c.querySelector('.line-supplier').value=s;if(m)c.querySelector('.line-method').value=m;filter(c);});totals();});totals();})();</script>
